import math
from fractions import Fraction

def is_pretty(m, n, alpha, k):
    return m * math.ceil(n * alpha) - n * math.floor(m * alpha) == k

def find_cool_pairs(alpha, k, limit):
    pretty_pairs = []
    for m in range(1, limit + 1):
        for n in range(1, limit + 1):
            if is_pretty(m, n, alpha, k):
                pretty_pairs.append((m, n))

    cool_pairs = []
    for m, n in pretty_pairs:
        is_cool = True
        if m > n:
            if is_pretty(m - n, n, alpha, k):
                is_cool = False
        if n > m:
            if is_pretty(m, n - m, alpha, k):
                is_cool = False
        if is_cool:
            cool_pairs.append((m, n))
    return cool_pairs

# Test for several k and alpha
alphas = [math.sqrt(2), math.sqrt(3), math.pi, math.e]
ks = [1, 2, 3, 4, 5, 6]
limit = 100

for alpha in alphas:
    print(f"Alpha: {alpha}")
    for k in ks:
        cool = find_cool_pairs(alpha, k, limit)
        print(f"k={k}, cool_count={len(cool)}")

